def _log_step(name, cn_name, pool, values, fmt=".4f", etf_names=None):
    labels = build_etf_display_names(pool, etf_names)
    parts = ["%s=%%s" % label for label in labels]
    template = "[%s] %s: " % (cn_name, name) + ", ".join(parts)
    formatted = tuple(format(v, fmt) for v in values)
    log.info(template, *formatted)
def compose_raw_weights(tilted_weights, trend_gates, crowd_penalties):
    n = len(tilted_weights)
    raw = np.zeros(n)
    for i in range(n):
        raw[i] = (
            tilted_weights[i]
            * trend_gates[i]
            * crowd_penalties[i]
        )
    return raw
def _as_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    try:
        return pd.Timestamp(value).date()
    except Exception:
        return value
def _context_trade_date(context):
    return _as_date(getattr(context, "current_dt", None))
def _same_iso_week(left, right):
    left = _as_date(left)
    right = _as_date(right)
    if left is None or right is None:
        return False
    return left.isocalendar()[:2] == right.isocalendar()[:2]
def _float_list(values):
    try:
        if hasattr(values, "tolist"):
            values = values.tolist()
    except Exception:
        pass
    return [float(value) for value in list(values or [])]
